class Solution {
    private int sum;
    public TreeNode convertBST(TreeNode root){
        traverse(root);
        return root;
    }
    private void traverse(TreeNode node){
        if(node==null)return;
        traverse(node.right);
        sum+=node.val;
        node.val=sum;
        traverse(node.left);
    }
}

code.kotlin:
class Solution {
    private var sum=0;
    fun convertBST(root:TreeNode?):TreeNode?{
        fun traverse(node:TreeNode?){
            if(node==null)return;
            traverse(node.right);
            sum+=node.`val`;
            node.`val`=sum;
            traverse(node.left)
        };
        traverse(root);
        return root
    }
}

